namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Hydraulic Press #A1", "Building 3 - Bay 7", new DateTime(2026, 6, 15)),
            new(2, "CNC Lathe #B2", "Building 1 - Bay 2", new DateTime(2026, 5, 20)),
            new(3, "Conveyor Belt #C3", "Warehouse 2", new DateTime(2026, 4, 10)),
            new(4, "Forklift #D4", "Loading Dock", new DateTime(2026, 6, 28)),
            new(5, "Welding Robot #E5", "Building 3 - Bay 12", new DateTime(2026, 3, 5)),
            new(6, "Air Compressor #F6", "Utility Room", new DateTime(2026, 6, 1)),
            new(7, "Overhead Crane #G7", "Building 2 - Bay 1", new DateTime(2026, 2, 18)),
            new(8, "Band Saw #H8", "Building 1 - Bay 5", new DateTime(2026, 5, 30)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? equipment;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (!ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            // First render (prerender): fetch from service and persist for the interactive render
            equipment = await EquipmentService.GetEquipmentAsync();
        }
        else
        {
            // Interactive render: reuse the data that was persisted during prerender
            equipment = restored;
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

